@startuml

enum Suit {
  DIAMONDS
  HEARTS
  SPADES
  CLUBS
}

enum ComparisonResult {
  LOWER
  EQUAL
  HIGHER
}

enum SoloType {
  TRUMP
  JACK
  QUEEN
}

abstract class Card {
  + id : string
  + compare(other : Card) : ComparisonResult
}

class Deck {
  + id : string
  + cardCount : int
}

class Player {
  + id : string
}

class ScoringTable {
  + id : string
}

class Round {
  + id : string
  + pointValue : int
}

class JackRound extends Round {}

class SoloRound extends Round {
  + soloType : SoloType
}

class MandatorySoloRound extends SoloRound {}

Player "1" -- "1" SoloRound : is player
ScoringTable "1" *-- "0..*" Round
Game "1" *-- "4" Player
Game "1" *-- "1" Deck
Game "1" *-- "1" ScoringTable
Deck "1" *-- "0..48" Card
Round "1" -- "1..*" Player : winning players

abstract class Game {
  + id : string
}

class Game {}

@enduml

